//! ONNX protobuf message types generated by prost from a pinned onnx.proto.
//!
//! `generated.rs` is written by `cargo xtask proto` from `proto/onnx.proto`
//! (ONNX v1.22.0, D31) and is never edited by hand; CI fails if regenerating
//! it changes anything.

#[rustfmt::skip]
#[allow(
    missing_docs,
    clippy::doc_markdown,
    clippy::doc_overindented_list_items,
    clippy::too_long_first_doc_paragraph,
    clippy::missing_const_for_fn,
    clippy::derive_partial_eq_without_eq,
    reason = "prost-generated code: its docs are onnx.proto's comments, and its shape is prost's"
)]
mod generated;

pub use generated::*;
